package io.github.rebrowser.continuity;

import static org.junit.Assert.*;
import io.github.rebrowser.bootstrap.*;
import io.github.rebrowser.engine.PartitionCatalog;
import java.lang.reflect.*;
import java.nio.file.*;
import java.util.*;
import org.junit.Test;

/** Actual receipt/ledger/gate pipeline with PRIVATE SYNTHETIC OS provenance, NOT Android signing. */
public final class SourceBootstrapTest {
    private static final String ROOT=new String(new char[64]).replace('\0','a');
    private static final byte[] CERT={1,2,3},OTHER={4,5,6};
    private static final class Fixture implements AutoCloseable {
        final Object app=new Object();final Path dir;final LastGoodSourceStore store;final byte[] epoch=new byte[16];
        final SigningIdentity.Identity signer;final CompiledSourceIdentity root;
        Fixture(boolean seeded)throws Exception{dir=Files.createTempDirectory("source-bootstrap-host-");store=new LastGoodSourceStore(dir);signer=SigningIdentity.fromSystemVerifiedCertificates(CERT,new byte[][]{CERT});Constructor<CompiledSourceIdentity> ctor=CompiledSourceIdentity.class.getDeclaredConstructor(String.class);ctor.setAccessible(true);root=ctor.newInstance(ROOT);if(seeded)store.seedVerifiedFresh(store.inspect(),new LastGoodSourceStore.SourceEpoch(signer.currentCertificateSha256(),ROOT,epoch),(a,b)->{});}
        SigningIdentity.OwnInspection own(Object owner,SigningIdentity.Identity identity,long version,long update)throws Exception{Constructor<SigningIdentity.OwnInspection> ctor=SigningIdentity.OwnInspection.class.getDeclaredConstructor(Object.class,SigningIdentity.Identity.class,long.class,long.class);assertTrue(Modifier.isPrivate(ctor.getModifiers()));ctor.setAccessible(true);return ctor.newInstance(owner,identity,version,update);}
        SourceBootstrap.Inspection evaluate(SigningIdentity.OwnInspection before,SigningIdentity.OwnInspection after,CompiledSourceIdentity source,long start,long now)throws Exception{
            Method method=SourceBootstrap.class.getDeclaredMethod("evaluateNative",Object.class,CompiledSourceIdentity.class,SigningIdentity.OwnInspection.class,SigningIdentity.OwnInspection.class,LastGoodSourceStore.ReadReceipt.class,long.class,long.class);assertTrue(Modifier.isPrivate(method.getModifiers()));method.setAccessible(true);return (SourceBootstrap.Inspection)invoke(method,null,app,source,before,after,store.confirmUnchanged(store.inspect()),start,now);
        }
        SourceBootstrap.Inspection inspect()throws Exception{SigningIdentity.OwnInspection own=own(app,signer,2,100);return evaluate(own,own,root,1000,1001);}
        @Override public void close()throws Exception{try(java.util.stream.Stream<Path> paths=Files.walk(dir)){Path[] all=paths.sorted(Comparator.reverseOrder()).toArray(Path[]::new);for(Path path:all)Files.delete(path);}}
    }
    private static Object invoke(Method method,Object owner,Object...args)throws Exception{try{return method.invoke(owner,args);}catch(InvocationTargetException e){if(e.getCause() instanceof Exception)throw (Exception)e.getCause();throw new AssertionError(e.getCause());}}
    private static SourceBootstrap.AcceptedContext transfer(SourceBootstrap.Inspection inspection,Object app,long now)throws Exception{Method method=SourceBootstrap.Inspection.class.getDeclaredMethod("transfer",Object.class,long.class);assertTrue(Modifier.isPrivate(method.getModifiers()));method.setAccessible(true);return (SourceBootstrap.AcceptedContext)invoke(method,inspection,app,now);}
    @Test public void productionUnconfiguredFastPathNeedsNoAndroidPmClockOrFilesystem(){assertEquals(SourceBootstrap.Status.UNCONFIGURED,SourceBootstrap.inspectOwn(null,null).status());}
    @Test public void stableExactPrivatePipelineIssuesOneNativeEpochContext()throws Exception{try(Fixture f=new Fixture(true)){SourceBootstrap.Inspection inspection=f.inspect();assertEquals(SourceBootstrap.Status.ACCEPTED_STABLE,inspection.status());SourceBootstrap.AcceptedContext context=transfer(inspection,f.app,1002);assertArrayEquals(f.epoch,context.dataEpoch());assertEquals(ROOT,context.rootSha256());assertEquals(f.signer.currentCertificateSha256(),context.signingSha256());assertThrows(SecurityException.class,()->transfer(inspection,f.app,1003));}}
    @Test public void nativeContextEpochIsDefensiveAndBindsGatePartitionPipeline()throws Exception{try(Fixture f=new Fixture(true)){SourceBootstrap.AcceptedContext context=transfer(f.inspect(),f.app,1002);byte[] copy=context.dataEpoch();copy[0]=9;assertEquals(0,context.dataEpoch()[0]);ComponentGate gate=ComponentGate.forNativeSource(ProcessRole.MAIN,()->ComponentGate.SourceView.acceptedNative(context,context.dataEpoch()));ComponentGate.BusinessPermit permit=gate.requireBusiness();gate.requireDataEpoch(permit,new byte[16]);PartitionCatalog partitions=new PartitionCatalog(gate,context.dataEpoch(),2);assertNotNull(partitions.create(PartitionCatalog.Domain.BROWSER,new Object(),permit));assertThrows(SecurityException.class,()->gate.requireDataEpoch(permit,copy));}}
    @Test public void missingMarkerNeverSeedsFreshInstallOrUnlocks()throws Exception{try(Fixture f=new Fixture(false)){SourceBootstrap.Inspection inspection=f.inspect();assertEquals(SourceBootstrap.Status.MISSING_BASELINE,inspection.status());assertFalse(Files.exists(f.dir.resolve("source-continuity.v1")));assertThrows(SecurityException.class,()->transfer(inspection,f.app,1002));}}
    @Test public void corruptAndUnfinishedMetadataRemainUncertainNotRepaired()throws Exception{try(Fixture f=new Fixture(true)){Files.write(f.dir.resolve("source-continuity.pending"),new byte[]{1});assertEquals(SourceBootstrap.Status.UNCERTAIN_METADATA,f.inspect().status());Files.delete(f.dir.resolve("source-continuity.pending"));Files.write(f.dir.resolve("source-continuity.v1"),new byte[]{1});assertEquals(SourceBootstrap.Status.UNCERTAIN_METADATA,f.inspect().status());assertEquals(1,Files.size(f.dir.resolve("source-continuity.v1")));}}
    @Test public void allNonStablePhasesRequireSeparateRecoveryNotBaselineShortcut()throws Exception{try(Fixture f=new Fixture(true)){byte[] next=new byte[16];next[0]=1;LastGoodSourceStore.View prepared=f.store.prepareReplacement(f.store.inspect(),new LastGoodSourceStore.SourceEpoch(new String(new char[64]).replace('\0','b'),ROOT,next),(a,b)->{});assertEquals(SourceBootstrap.Status.RECOVERY_REQUIRED,f.inspect().status());LastGoodSourceStore.View destroying=f.store.markDestructionMayStart(prepared,(a,b)->{});assertEquals(SourceBootstrap.Status.RECOVERY_REQUIRED,f.inspect().status());f.store.recordVerifiedEmptyEpoch(destroying,(a,b)->{});assertEquals(SourceBootstrap.Status.RECOVERY_REQUIRED,f.inspect().status());}}
    @Test public void differentCurrentSignerCannotBorrowSameRoot()throws Exception{try(Fixture f=new Fixture(true)){SigningIdentity.Identity other=SigningIdentity.fromSystemVerifiedCertificates(OTHER,new byte[][]{OTHER});SigningIdentity.OwnInspection own=f.own(f.app,other,2,100);assertEquals(SourceBootstrap.Status.SOURCE_MISMATCH,f.evaluate(own,own,f.root,1000,1001).status());}}
    @Test public void differentCompiledRootCannotBorrowSameSigner()throws Exception{try(Fixture f=new Fixture(true)){Constructor<CompiledSourceIdentity> ctor=CompiledSourceIdentity.class.getDeclaredConstructor(String.class);ctor.setAccessible(true);CompiledSourceIdentity other=ctor.newInstance(new String(new char[64]).replace('\0','b'));SigningIdentity.OwnInspection own=f.own(f.app,f.signer,2,100);assertEquals(SourceBootstrap.Status.SOURCE_MISMATCH,f.evaluate(own,own,other,1000,1001).status());}}
    @Test public void androidLineageMetadataAloneDoesNotAuthorizeResume()throws Exception{try(Fixture f=new Fixture(true)){SigningIdentity.Identity rotated=SigningIdentity.fromSystemVerifiedCertificates(OTHER,new byte[][]{CERT,OTHER});assertTrue(rotated.acceptsLastGoodSigner(f.signer.currentCertificateSha256()));SigningIdentity.OwnInspection own=f.own(f.app,rotated,3,200);assertEquals(SourceBootstrap.Status.SOURCE_MISMATCH,f.evaluate(own,own,f.root,1000,1001).status());}}
    @Test public void foreignNativeApplicationCannotContributeProvenance()throws Exception{try(Fixture f=new Fixture(true)){SigningIdentity.OwnInspection wrong=f.own(new Object(),f.signer,2,100);assertEquals(SourceBootstrap.Status.UNAVAILABLE,f.evaluate(wrong,wrong,f.root,1000,1001).status());}}
    @Test public void changedPackageVersionOrUpdateDuringInspectionRejects()throws Exception{try(Fixture f=new Fixture(true)){SigningIdentity.OwnInspection before=f.own(f.app,f.signer,2,100);for(SigningIdentity.OwnInspection changed:new SigningIdentity.OwnInspection[]{f.own(f.app,f.signer,3,100),f.own(f.app,f.signer,2,200)})assertEquals(SourceBootstrap.Status.UNAVAILABLE,f.evaluate(before,changed,f.root,1000,1001).status());}}
    @Test public void changedOwnSignerDuringInspectionCannotPublishStalePair()throws Exception{try(Fixture f=new Fixture(true)){SigningIdentity.OwnInspection before=f.own(f.app,f.signer,2,100);SigningIdentity.Identity changed=SigningIdentity.fromSystemVerifiedCertificates(OTHER,new byte[][]{OTHER});assertEquals(SourceBootstrap.Status.UNAVAILABLE,f.evaluate(before,f.own(f.app,changed,2,100),f.root,1000,1001).status());}}
    @Test public void inspectionClockRollbackOrLongWaitNeverCreatesReceipt()throws Exception{try(Fixture f=new Fixture(true)){SigningIdentity.OwnInspection own=f.own(f.app,f.signer,2,100);assertEquals(SourceBootstrap.Status.UNAVAILABLE,f.evaluate(own,own,f.root,1000,999).status());assertEquals(SourceBootstrap.Status.UNAVAILABLE,f.evaluate(own,own,f.root,1000,31001).status());}}
    @Test public void expiredTransferAttemptStaysSpentNoClockRetry()throws Exception{try(Fixture f=new Fixture(true)){SourceBootstrap.Inspection inspection=f.inspect();assertThrows(SecurityException.class,()->transfer(inspection,f.app,31001));assertThrows(SecurityException.class,()->transfer(inspection,f.app,1002));}}
    @Test public void foreignTransferAttemptDoesNotProduceOrRetryAcceptedContext()throws Exception{try(Fixture f=new Fixture(true)){SourceBootstrap.Inspection inspection=f.inspect();assertThrows(SecurityException.class,()->transfer(inspection,new Object(),1002));assertThrows(SecurityException.class,()->transfer(inspection,f.app,1002));}}
    @Test public void readReceiptRejectsLedgerChangeBetweenReadAndConfirm()throws Exception{try(Fixture f=new Fixture(true)){LastGoodSourceStore.View original=f.store.inspect();byte[] next=new byte[16];next[0]=1;f.store.prepareReplacement(original,new LastGoodSourceStore.SourceEpoch(new String(new char[64]).replace('\0','b'),ROOT,next),(a,b)->{});assertThrows(IllegalStateException.class,()->f.store.confirmUnchanged(original));}}
    @Test public void readReceiptIsIssuerBoundNotCallerSnapshotData()throws Exception{try(Fixture a=new Fixture(true);Fixture b=new Fixture(true)){assertThrows(IllegalStateException.class,()->a.store.confirmUnchanged(b.store.inspect()));for(Constructor<?> ctor:LastGoodSourceStore.ReadReceipt.class.getDeclaredConstructors())assertFalse(Modifier.isPublic(ctor.getModifiers()));}}
    @Test public void nativePublicationCannotReviveAfterFenceOrDuplicateCallback(){
        io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate publication=new io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate();io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate.Ticket ticket=publication.begin();assertTrue(publication.hasPendingHandoff());publication.revoke();assertTrue(publication.hasPendingHandoff());assertFalse(publication.finish(ticket));assertFalse(publication.finish(ticket));assertFalse(publication.hasPendingHandoff());assertThrows(IllegalStateException.class,publication::begin);
    }
    @Test public void currentPublicationHasOneNormalHandoffNotTwoAcceptedResults(){
        io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate publication=new io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate();io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate.Ticket ticket=publication.begin();assertTrue(publication.confirmSubmission(ticket));assertTrue(publication.finish(ticket));assertFalse(publication.finish(ticket));assertThrows(IllegalStateException.class,publication::begin);
    }
    @Test public void foreignPublicationTicketCannotPublishAnotherApplication(){
        io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate a=new io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate(),b=new io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate();io.github.rebrowser.bootstrap.StartupCoordinator.PublicationGate.Ticket ticket=a.begin();assertThrows(SecurityException.class,()->b.finish(ticket));assertTrue(a.hasPendingHandoff());a.finish(ticket);
    }
    @Test public void transferClockRollbackSpendsReceiptWithoutUnlock()throws Exception{try(Fixture f=new Fixture(true)){SourceBootstrap.Inspection inspection=f.inspect();assertThrows(SecurityException.class,()->transfer(inspection,f.app,999));assertThrows(SecurityException.class,()->transfer(inspection,f.app,1002));}}
    @Test public void nativeStoreRequiresExactFixedNamespaceNotAnotherSelectedDirectory()throws Exception{try(Fixture f=new Fixture(true)){f.store.requireNativeBootstrapPath(f.dir);assertThrows(java.io.IOException.class,()->f.store.requireNativeBootstrapPath(f.dir.resolve("other")));}}
    @Test public void callbackBeforeSubmissionReturnCannotMintTrustLater(){StartupCoordinator.PublicationGate p=new StartupCoordinator.PublicationGate();StartupCoordinator.PublicationGate.Ticket t=p.begin();assertFalse(p.finish(t));assertFalse(p.confirmSubmission(t));assertFalse(p.finish(t));}
    @Test public void unknownSubmissionCannotReviveThroughLateCallback(){StartupCoordinator.PublicationGate p=new StartupCoordinator.PublicationGate();StartupCoordinator.PublicationGate.Ticket t=p.begin();p.rejectSubmission(t);assertFalse(p.confirmSubmission(t));assertTrue(p.hasPendingHandoff());assertFalse(p.finish(t));assertFalse(p.hasPendingHandoff());}
    @Test public void positiveSubmissionCanBeFencedBeforeCallback(){StartupCoordinator.PublicationGate p=new StartupCoordinator.PublicationGate();StartupCoordinator.PublicationGate.Ticket t=p.begin();assertTrue(p.confirmSubmission(t));p.rejectSubmission(t);assertFalse(p.finish(t));}
    @Test public void foreignSubmissionCannotConfirmOrRejectPendingOwner(){StartupCoordinator.PublicationGate a=new StartupCoordinator.PublicationGate(),b=new StartupCoordinator.PublicationGate();StartupCoordinator.PublicationGate.Ticket t=a.begin();assertThrows(SecurityException.class,()->b.confirmSubmission(t));assertThrows(SecurityException.class,()->b.rejectSubmission(t));assertTrue(a.confirmSubmission(t));assertTrue(a.finish(t));}
    @Test public void noPublicAlternateSignerProviderOrReceiptConstructor(){assertEquals(0,SourceBootstrap.class.getConstructors().length);for(Class<?> type:new Class<?>[]{SourceBootstrap.Inspection.class,SourceBootstrap.AcceptedContext.class,SigningIdentity.OwnInspection.class})for(Constructor<?> c:type.getDeclaredConstructors())assertFalse(Modifier.isPublic(c.getModifiers()));}
}
